/* vfork_example.c: Demonstrate vfork for immediate exec */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int global_var = 100;

int main(void) {
    pid_t pid;
    int status;

    // Caution: vfork requires the child to immediately exec or _exit.
    // We must avoid modifying global_var in the child before exec.

    printf("Parent PID: %d. Global var: %d\n", getpid(), global_var);

    pid = vfork();

    if (pid == -1) {
        perror("vfork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        // The child MUST NOT modify stack/data variables or return here
        // The child shares memory with the parent until exec.

        char *const argv[] = {"/bin/echo", "Hello from the vforked child!", NULL};
        char *const envp[] = {NULL};

        printf("Child PID: %d. Attempting exec...\n", getpid());

        // This exec replaces the child's image and unlocks the parent.
        execve(argv[0], argv, envp);

        // If execve fails, the child must terminate cleanly using _exit(2)
        perror("execve failed");
        _exit(1);

    } else { // Parent process
        // Parent remains suspended until child calls exec or _exit.
        // Execution resumes here only after the child successfully execs.
        printf("Parent continues after child exec (Child PID: %d)\n", pid);

        // Parent waits for the newly exec'd child to finish executing /bin/echo
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }

        printf("Parent finished waiting. Child exit status: %d\n", WEXITSTATUS(status));
    }

    return 0;
}
